def run():
    prod_17 = Product.objects.filter(ProductName__icontains='17KG').first()
    if not prod_17:
        print('Error: 17KG Product not found in database!')
        return

    print(f'Using Product: [{prod_17.ProductId}] {prod_17.ProductName} (Base Price: {prod_17.SalesPrice})')

    updated = 0
    not_found = []
    for name, code, price in CUSTOMER_PRICES:
        ledger = Ledger.objects.filter(LedgerName__iexact=name).first()
        if not ledger and code:
            ledger = Ledger.objects.filter(CustomerCode=code).first()
        if ledger:
            CustomerProductPrice.objects.update_or_create(
                CustomerLedger=ledger,
                Product=prod_17,
                defaults={'SpecialPrice': Decimal(str(price))}
            )
            updated += 1
        else:
            not_found.append(f'{name} (Code: {code})')

    print(f'\nSuccessfully updated {updated} customer special prices.')
    if not_found:
        print(f'Customers not matched ({len(not_found)}):')
        for nf in not_found[:10]:
            print('  -', nf)
    print(f'Total CustomerProductPrice records in DB: {CustomerProductPrice.objects.count()}')

if __name__ == '__main__':
    run()
